        context.prec = 100

        total = _ZERO

        for new_line in new_lines:
            if new_line.get("DEL_FLG") == "Y":
                continue

            quantity = _numeric(new_line.get("QTY", ""))
            unit_price = _numeric(new_line.get("UNIT_PRC", ""))
            extension = _round_cents(quantity * unit_price)

            new_line["EXT_AMT"] = float(extension)
